#[derive(Debug, PartialEq, Eq)]
pub enum LookupError {
    Missing { key: String },
    Unavailable { retryable: bool },
}

pub fn lookup(key: &str) -> Result<u32, LookupError> {
    match key {
        "apple" => Ok(3),
        "pear" => Ok(7),
        "offline" => Err(LookupError::Unavailable { retryable: true }),
        _ => Err(LookupError::Missing { key: key.into() }),
    }
}

