use crate::catalog::{lookup, LookupError};

pub fn total(keys: &[&str]) -> Result<u32, LookupError> {
    keys.iter().try_fold(0, |sum, key| lookup(key).map(|value| sum + value))
}

pub fn describe(key: &str) -> String {
    match lookup(key) {
        Ok(value) => format!("{key}={value}"),
        Err(LookupError::Missing { key }) => format!("missing:{key}"),
        Err(LookupError::Unavailable { retryable }) => format!("unavailable:retryable={retryable}"),
    }
}

