use catalog::{catalog::{lookup, LookupError}, consumer::{total, describe}};
#[test]
fn public_contract() {
    assert_eq!(lookup("apple"), Ok(3));
    assert_eq!(lookup("pear"), Ok(7));
    assert_eq!(total(&[]), Ok(0));
    assert_eq!(total(&["apple", "pear", "apple"]), Ok(13));
    for key in ["", "unknown", "雪"] {
        assert_eq!(lookup(key), Err(LookupError::Missing { key: key.into() }));
        assert_eq!(total(&["apple", key, "offline"]), Err(LookupError::Missing { key: key.into() }));
        assert_eq!(describe(key), format!("missing:{key}"));
    }
    assert_eq!(lookup("offline"), Err(LookupError::Unavailable { retryable: true }));
    assert_eq!(total(&["offline", "unknown"]), Err(LookupError::Unavailable { retryable: true }));
    assert_eq!(describe("apple"), "apple=3");
    assert_eq!(describe("offline"), "unavailable:retryable=true");
}
